<?php
namespace App\Services\Coupons;
use App\Models\Coupon; use App\Models\CouponReservation; use App\Models\CouponUsage; use App\Models\Order; use Illuminate\Support\Facades\DB;
class CouponReservationService {
 public function reserve(Coupon $coupon,Order $order,float $subtotal): CouponReservation { return DB::transaction(function()use($coupon,$order,$subtotal){$c=Coupon::whereKey($coupon->id)->lockForUpdate()->firstOrFail(); if(!$c->is_active||($c->starts_at&&$c->starts_at->isFuture())||($c->expires_at&&$c->expires_at->isPast())||($c->min_order_amount&&$subtotal<(float)$c->min_order_amount)) throw new \RuntimeException('كوبون الخصم غير صالح.'); $active=CouponReservation::where('coupon_id',$c->id)->where('status','reserved')->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->count(); $used=CouponUsage::where('coupon_id',$c->id)->count(); if($c->max_uses!==null&&$used+$active>=(int)$c->max_uses) throw new \RuntimeException('تم استهلاك الحد الأقصى للكوبون.'); if($c->max_uses_per_user!==null&&$order->user_id){$u=CouponUsage::where('coupon_id',$c->id)->where('user_id',$order->user_id)->count();$r=CouponReservation::where('coupon_id',$c->id)->where('user_id',$order->user_id)->where('status','reserved')->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->count();if($u+$r>=(int)$c->max_uses_per_user)throw new \RuntimeException('تم استهلاك حد استخدام الكوبون لهذا المستخدم.');} $discount=max(0,min($subtotal,(float)$c->calculateDiscount($subtotal))); return CouponReservation::firstOrCreate(['order_id'=>$order->id],['coupon_id'=>$c->id,'user_id'=>$order->user_id,'status'=>'reserved','discount_amount'=>$discount,'expires_at'=>now()->addHour()]);},3); }
 public function consume(Order $order): void {DB::transaction(function()use($order){$r=CouponReservation::where('order_id',$order->id)->lockForUpdate()->first();if(!$r||$r->status==='consumed')return;if($r->status==='released')throw new \RuntimeException('تم تحرير حجز الكوبون لهذا الطلب.');CouponUsage::firstOrCreate(['coupon_id'=>$r->coupon_id,'order_id'=>$order->id],['user_id'=>$order->user_id,'session_id'=>$order->session_id,'ip_address'=>request()?->ip()]);$r->update(['status'=>'consumed','consumed_at'=>now()]);},3);}
 public function release(Order $order): void {DB::transaction(function()use($order){$r=CouponReservation::where('order_id',$order->id)->where('status','reserved')->lockForUpdate()->first();if($r)$r->update(['status'=>'released','released_at'=>now()]);},3);}
}
